package com.citacloud.app.models; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="signos_vitales") public class SignosVitales {@Id @GeneratedValue private UUID id;@Column(name="empresa_id") private UUID empresaId;@Column(name="paciente_id") private UUID pacienteId;@Column(name="cita_id") private UUID citaId;private BigDecimal peso,altura,temperatura,imc;@Column(name="presion_sistolica")private Integer presionSistolica;@Column(name="presion_diastolica")private Integer presionDiastolica;public UUID getId(){return id;}public UUID getEmpresaId(){return empresaId;}public void setEmpresaId(UUID v){empresaId=v;}public UUID getPacienteId(){return pacienteId;}public void setPacienteId(UUID v){pacienteId=v;}public UUID getCitaId(){return citaId;}public void setCitaId(UUID v){citaId=v;}public BigDecimal getPeso(){return peso;}public void setPeso(BigDecimal v){peso=v;}public BigDecimal getAltura(){return altura;}public void setAltura(BigDecimal v){altura=v;}public BigDecimal getTemperatura(){return temperatura;}public void setTemperatura(BigDecimal v){temperatura=v;}public BigDecimal getImc(){return imc;}public void setImc(BigDecimal v){imc=v;}public Integer getPresionSistolica(){return presionSistolica;}public void setPresionSistolica(Integer v){presionSistolica=v;}public Integer getPresionDiastolica(){return presionDiastolica;}public void setPresionDiastolica(Integer v){presionDiastolica=v;}}
